-- Chaos top bar
-- A row of engraved icon buttons anchored to the top of the game window.
-- Every button is optional: it is shown only when the module it controls is
-- loaded and exposes something we know how to call.  Nothing here errors if a
-- module is missing, renamed or has a different API (all calls are pcall'd).
--
-- Icons: /images/chaos/small/topbutton_<id>.png (+ _hover), generated by
-- client/tools/gen_theme_art.py.  UNTESTED against a real OTClient runtime.

ChaosTopBar = {}

local ICON_DIR = '/images/chaos/small/topbutton_'
local BAR_PADDING = 16        -- left+right margins in topbar.otui
local BUTTON_SIZE = 32
local BUTTON_SPACING = 3
local ADMIN_MIN_GROUP = 4     -- TFS: 4 = gamemaster and above

local topBar
local buttonsPanel
local buttons = {}            -- id -> widget
local adminOverride = nil     -- set via ChaosTopBar.setAdmin() (e.g. from a server opcode)
local refreshEvent

-- ---------------------------------------------------------------- helpers
-- Sandboxed module environments fall back to _G through __index, so use
-- rawget to avoid picking up an unrelated global called "toggle".
local function getModule(name)
  local m = modules and modules[name]
  if type(m) ~= 'table' then return nil end
  return m
end

local function resolvePath(root, path)
  local cur = root
  for key in string.gmatch(path, '[^%.]+') do
    if type(cur) ~= 'table' then return nil end
    cur = rawget(cur, key)
    if cur == nil then return nil end
  end
  return cur
end

local function isAlive(widget)
  if not widget then return false end
  local ok, destroyed = pcall(function() return widget:isDestroyed() end)
  return ok and not destroyed
end

local function toggleWidget(w)
  if w:isVisible() then w:hide() else w:show(); w:raise(); w:focus() end
end

-- Finds a callable action for an entry or returns nil.
local function findAction(entry)
  if entry.custom then
    return entry.custom
  end
  for _, modName in ipairs(entry.modules or {}) do
    local m = getModule(modName)
    if m then
      for _, path in ipairs(entry.fns or {}) do
        local fn = resolvePath(m, path)
        if type(fn) == 'function' then
          return function() fn() end
        end
      end
      for _, varName in ipairs(entry.windows or {}) do
        local w = rawget(m, varName)
        if w and type(w) ~= 'function' and isAlive(w) then
          return function() toggleWidget(w) end
        end
      end
    end
  end
  return nil
end

local function logout()
  local gi = getModule('game_interface')
  if gi and type(rawget(gi, 'tryLogout')) == 'function' then
    gi.tryLogout()
  elseif g_game and g_game.isOnline() then
    g_game.safeLogout()
  end
end

-- Admin / gamemaster check.  Defaults to false.  Uses whichever accessor the
-- local player exposes in this client build; a server can also call
-- ChaosTopBar.setAdmin(true) (e.g. from an extended opcode handler).
local function hasAdminAccess()
  if adminOverride ~= nil then return adminOverride end
  if not (g_game and g_game.isOnline and g_game.isOnline()) then return false end
  local ok, result = pcall(function()
    local player = g_game.getLocalPlayer()
    if not player then return false end
    for _, name in ipairs({ 'isAdmin', 'isGamemaster', 'isGameMaster' }) do
      local f = player[name]
      if type(f) == 'function' and f(player) == true then return true end
    end
    for _, name in ipairs({ 'getGroup', 'getGroupId', 'getAccess', 'getAccessLevel' }) do
      local f = player[name]
      if type(f) == 'function' then
        local v = f(player)
        if type(v) == 'number' and v >= ADMIN_MIN_GROUP then return true end
      end
    end
    return false
  end)
  return ok and result == true
end

-- ---------------------------------------------------------------- entries
-- id      -> icon name (topbutton_<id>)
-- modules -> candidate module names (first loaded one that has a usable call wins)
-- fns     -> function paths inside the module env, e.g. 'toggle' or 'Stash.Toggle'
-- windows -> fallback: global variable names holding a window widget to show/hide
-- admin   -> only visible when hasAdminAccess()
local ENTRIES = {
  { id = 'inventory',     tip = 'Inventory',      modules = { 'game_inventory' },  fns = { 'toggle' }, windows = { 'inventoryWindow' } },
  { id = 'skills',        tip = 'Skills',         modules = { 'game_skills' },     fns = { 'toggle' }, windows = { 'skillsWindow' } },
  { id = 'battlelist',    tip = 'Battle List',    modules = { 'game_battle' },     fns = { 'toggle' }, windows = { 'battleWindow' } },
  { id = 'vip',           tip = 'VIP List',       modules = { 'game_viplist' },    fns = { 'toggle' }, windows = { 'vipWindow' } },
  { id = 'spells',        tip = 'Spells',         modules = { 'game_spelllist' },  fns = { 'toggle' }, windows = { 'spelllistWindow' } },
  { id = 'quests',        tip = 'Quest Log',      modules = { 'game_questlog' },   fns = { 'toggle', 'show' } },
  { id = 'market',        tip = 'Market / Store', modules = { 'game_market', 'game_shop' }, fns = { 'toggle' } },
  { id = 'bank',          tip = 'Bank',           modules = { 'game_bank' },       fns = { 'toggle', 'Toggle' }, windows = { 'bankingWindow' } },
  { id = 'stash',         tip = 'Supply Stash',   modules = { 'game_stash' },      fns = { 'Stash.Toggle', 'toggle' } },
  { id = 'autoloot',      tip = 'Auto Loot',      modules = { 'game_autoloot' },   fns = { 'toggle' } },
  { id = 'daily',         tip = 'Daily Reward',   modules = { 'game_daily' },      fns = { 'toggle', 'Show' } },
  { id = 'battlepass',    tip = 'Battle Pass',    modules = { 'game_battlepass' }, fns = { 'm_BattlepassFunctions.open', 'toggle' } },
  { id = 'passivetree',   tip = 'Passive Tree',   modules = { 'game_passivetree' }, fns = { 'toggle' } },
  { id = 'dungeons',      tip = 'Dungeons',       modules = { 'game_dungeons' },   fns = { 'toggle' } },
  { id = 'events',        tip = 'Events',         modules = { 'game_event' },      fns = { 'Event.Toggle', 'toggle' } },
  { id = 'infinitytower', tip = 'Infinity Tower', modules = { 'game_infinitytower' }, fns = { 'toggle' } },
  { id = 'minimap',       tip = 'Minimap',        modules = { 'game_realminimap', 'game_minimap' }, fns = { 'toggle' } },
  { id = 'ranking',       tip = 'Ranking',        modules = { 'game_highscore', 'game_ranking' }, fns = { 'toggle' } },
  { id = 'notifications', tip = 'Notifications',  modules = { 'game_chaosnotify' }, fns = { 'toggle', 'showAll' } },
  { id = 'options',       tip = 'Options',        modules = { 'client_options' },  fns = { 'toggle' } },
  { id = 'help',          tip = 'Help',           modules = { 'game_guide', 'game_bugreport' }, fns = { 'toggle', 'show' } },
  { id = 'admin',         tip = 'Admin Panel',    modules = { 'game_admin' },      fns = { 'toggle' }, admin = true },
  { id = 'logout',        tip = 'Logout',         custom = logout },
}

-- ---------------------------------------------------------------- widgets
local function setIcon(button, id, hovered)
  button:setImageSource(ICON_DIR .. id .. (hovered and '_hover' or ''))
end

local function createButton(entry)
  local button = g_ui.createWidget('ChaosTopButton', buttonsPanel)
  button:setId('chaosTop_' .. entry.id)
  button:setTooltip(entry.tip)
  setIcon(button, entry.id, false)
  button.onHoverChange = function(widget, hovered) setIcon(widget, entry.id, hovered) end
  button.onClick = function()
    local action = findAction(entry)
    if not action then return end
    local ok, err = pcall(action)
    if not ok then g_logger.error('[chaos_topbar] ' .. entry.id .. ': ' .. tostring(err)) end
  end
  button:setVisible(false)
  buttons[entry.id] = button
  return button
end

-- Re-evaluates which icons are visible and resizes the bar to fit.
function ChaosTopBar.refresh()
  if not isAlive(topBar) then return end
  local count = 0
  for _, entry in ipairs(ENTRIES) do
    local button = buttons[entry.id]
    if button then
      local show = findAction(entry) ~= nil
      if show and entry.admin then show = hasAdminAccess() end
      button:setVisible(show)
      if show then count = count + 1 end
    end
  end
  local width = count * BUTTON_SIZE + math.max(count - 1, 0) * BUTTON_SPACING + BAR_PADDING
  topBar:setWidth(math.max(width, 40))
  topBar:setVisible(count > 0 and g_game.isOnline())
end

-- Lets a server script (extended opcode) grant/revoke the admin icon.
function ChaosTopBar.setAdmin(value)
  adminOverride = value and true or false
  ChaosTopBar.refresh()
end

-- Lets other modules add their own icon: entry has the same fields as ENTRIES.
-- The icon image must exist as /images/chaos/small/topbutton_<id>.png.
function ChaosTopBar.addEntry(entry)
  if not entry or not entry.id or buttons[entry.id] then return end
  table.insert(ENTRIES, entry)
  if isAlive(buttonsPanel) then createButton(entry) end
  ChaosTopBar.refresh()
end

local function scheduleRefresh()
  -- game modules finish their own init a moment after onGameStart
  if refreshEvent then removeEvent(refreshEvent) end
  refreshEvent = scheduleEvent(function()
    refreshEvent = nil
    ChaosTopBar.refresh()
  end, 400)
end

local function onGameStart()
  ChaosTopBar.refresh()
  scheduleRefresh()
  scheduleEvent(ChaosTopBar.refresh, 3000)
end

local function onGameEnd()
  adminOverride = nil
  if isAlive(topBar) then topBar:hide() end
end

-- ---------------------------------------------------------------- lifecycle
function init()
  g_ui.importStyle('topbar')

  local parent
  local gi = getModule('game_interface')
  if gi and type(rawget(gi, 'getRootPanel')) == 'function' then
    parent = gi.getRootPanel()
  end
  parent = parent or g_ui.getRootWidget()

  topBar = g_ui.createWidget('ChaosTopBar', parent)
  buttonsPanel = topBar:getChildById('buttons')
  topBar:raise()

  for _, entry in ipairs(ENTRIES) do
    createButton(entry)
  end

  connect(g_game, { onGameStart = onGameStart, onGameEnd = onGameEnd })
  if g_game.isOnline() then onGameStart() end
end

function terminate()
  disconnect(g_game, { onGameStart = onGameStart, onGameEnd = onGameEnd })
  if refreshEvent then removeEvent(refreshEvent) refreshEvent = nil end
  if isAlive(topBar) then topBar:destroy() end
  topBar, buttonsPanel, buttons = nil, nil, {}
  ChaosTopBar = nil
end
